{
  "$schema": "https://agent-plugins.org/schemas/1.0.0/plugin.schema.json",
  "author": {
    "email": "alexi.fs341@gmail.com",
    "name": "Alexi Burgos"
  },
  "description": "Análisis institucional y estadística avanzada: 17 habilidades, con protocolo transversal de 7 niveles para inferencia, modelos, calidad y automatización; normas IPSS/PNM acotadas a sus proyectos.",
  "extensions": {
    "com.openai": {
      "interface": {
        "category": "Productivity",
        "defaultPrompt": "Ayúdame a analizar y comunicar estos datos institucionales; usa solo las habilidades necesarias para mi encargo.",
        "developerName": "Alexi Burgos",
        "displayName": "Análisis institucional de Alexi",
        "longDescription": "Herramientas personales para preparar datos, verificar matrícula y retención IPSS, analizar encuestas, mantener el reporte Power BI PNM y comunicar resultados con evidencia. Incorpora un protocolo estadístico transversal de siete niveles para análisis descriptivo e inferencial, modelos, automatización, calidad de datos, anomalías e innovación, también fuera de IPSS. Incluye plantilla IPSS y recursos de verificación.",
        "shortDescription": "Datos y comunicación trazable"
      }
    }
  },
  "keywords": [
    "analisis",
    "IPSS",
    "SIES",
    "PNM",
    "comunicacion",
    "estadistica",
    "inferencia",
    "modelado",
    "calidad de datos",
    "automatizacion"
  ],
  "name": "analisis-institucional-alexi",
  "version": "1.1.4"
}
